SELECT w.web_name, hd.hd_vehicle_count, sm.sm_carrier, SUM(ws.ws_net_paid_inc_ship) AS total_paid_ship, MAX(ws.ws_ext_discount_amt) AS max_discount, ROW_NUMBER() OVER (PARTITION BY hd.hd_vehicle_count ORDER BY SUM(ws.ws_net_paid_inc_ship) DESC) AS high_paid_rank FROM web_sales ws JOIN web_site w ON ws.ws_web_site_sk = w.web_site_sk JOIN household_demographics hd ON ws.ws_bill_hdemo_sk = hd.hd_demo_sk JOIN ship_mode sm ON ws.ws_ship_mode_sk = sm.sm_ship_mode_sk WHERE ws.ws_quantity BETWEEN 5 AND 15 AND ws.ws_ext_tax > 0 GROUP BY w.web_name, hd.hd_vehicle_count, sm.sm_carrier HAVING SUM(ws.ws_net_paid_inc_ship) > 1000 ORDER BY high_paid_rank ASC, w.web_name
